def make_finding(raw):
    fid, name, description, refs, value_kind, required = raw
    kind = next((value for token, value in KIND_BY_TOKEN if token in fid), "definition")
    subject = name.lower()
    return {"id":fid,"name":name,"description":description,"source_refs":refs,"questions":[
        {"id":fid+"-q01","text":f"What identities, types, roles, scope, versions and explicit values define {subject}?","kind":kind,"answer_data":["identifiers and classifications","roles and scope","versions and validity","values and explicit unknowns"]},
        {"id":fid+"-q02","text":f"Which authority, source, method, evidence, event time and knowledge time support {subject}?","kind":"provenance","answer_data":["authority","source and method","supporting and contradicting evidence","event and knowledge time","confidence and uncertainty"]},
        {"id":fid+"-q03","text":f"How is {subject} validated, accessed, changed, contested, corrected and retained?","kind":"validation","answer_data":["validation and profile rules","access and disclosure","change and dispute","lineage","retention and disposition"]}],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured test-execution data for "+subject+".","value_kind":value_kind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing test-execution record for "+subject+" with authority, time, provenance and access marking.","media_or_form":["logical test-execution assertion","plan, configuration, event, observation, result, evidence or review reference"],"serial":True,"identity_strategy":"Execution identifier plus "+fid+" assertion, artifact or event identifier; name, date, timestamp and digest never identify the execution alone.","source_refs":refs}],
        "inline_only_rationale":None}

def structure():
    bundles = []
    for bid, name, description, rationale, refs, layers in BUNDLES:
        made_layers = []
        for lid, lname, ldescription, lrefs, findings in layers:
            made_layers.append({"id":lid,"name":lname,"description":ldescription,"source_refs":lrefs,"findings":[make_finding(f) for f in findings]})
        bundles.append({"id":bid,"name":name,"description":description,"rationale":rationale,"source_refs":refs,"layers":made_layers})
    return {"bundles":bundles}

